/* Generated by Trae Work */
/* 全站关键词搜索：索引课程/大纲章节/笔记要点与详解/数学小节例题/时间线/真题/刷题，多关键词 AND 匹配 + 相关度排序 */
"use strict";
(function () {

  function buildIndex() {
    const idx = [];
    const push = (cat, title, text, href, extra) => {
      idx.push({ cat, title, text: String(text || ""), href, extra: extra || "" });
    };

    /* 自考课程（含章节名） */
    (SITE_DATA.zikao.courses || []).forEach(c => {
      const chapters = (c.chapters || []).map((t, i) => `${i + 1}.${t}`).join("；");
      push("课程", `${c.code} ${c.name}`, `自考 ${c.kind} ${chapters}`, `zikao.html#course-${c.code}`,
        c.has_syllabus ? "官方大纲已收录" : "大纲暂缺");
    });

    /* 官方大纲逐章考核知识点（DEEP.syllabus：5 门） */
    const DEEP = window.DEEP || {};
    Object.keys(DEEP.syllabus || {}).forEach(code => {
      const syl = DEEP.syllabus[code];
      if (!syl || !syl.chapters) return;
      const cname = (SITE_DATA.zikao.courses.find(c => c.code === code) || {}).name || "";
      syl.chapters.forEach(ch => {
        const kps = (ch.points || []).map(p =>
          typeof p === "string" ? p : p.text + (p.subs && p.subs.length ? "（" + p.subs.join("；") + "）" : "")
        ).join("；");
        const secs = (ch.sections || []).join("；");
        push("大纲考点", `${code} ${cname} · ${ch.title || ""}`, kps + "；" + secs, `zikao.html#course-${code}`, "官方大纲");
      });
    });

    /* 课程笔记：每章要点 + 知识点详解 */
    const ND = window.NOTES_DEEP || {};
    Object.keys(ND).forEach(code => {
      const course = ND[code];
      if (!course || !course.chapters) return;
      course.chapters.forEach(ch => {
        const pts = (ch.points || []).join("；");
        const dts = (ch.details || []).map(d => `${d.k}：${d.v}`).join("；");
        push("课程笔记", `${code} ${course.name || ""} · ${ch.title}`, pts + "；" + dts, `notes.html#${code}`, "笔记要点+详解");
      });
    });

    /* 高中数学：小节讲解 + 例题 + 测验 */
    (window.MATH_CHAPTERS || []).forEach(ch => {
      const secs = (ch.sections || []).map(s => `${s.title}。${s.text}`).join("；");
      const exs = (ch.examples || []).map(e => `例：${e.q} ${e.ans || ""}`).join("；");
      const qs = (ch.quiz || []).map(q => q.q).join("；");
      push("高中数学", `${ch.grade} · ${ch.title}`, secs + "；" + exs + "；" + qs, `math.html#${ch.id}`, "含例题与测验");
    });

    /* 408 大纲骨架 */
    const ky = SITE_DATA.kaoyan || {};
    ((ky.exam408 || {}).subjects || []).forEach(s => {
      push("408 大纲", `408 ${s.name}`, (s.chapters || []).join("；"), "kaoyan.html", `${s.score} 分`);
    });

    /* 时间线事件 */
    (SITE_DATA.timeline || []).forEach(e => {
      push("时间线", `${e.date_start}${e.date_end ? "~" + e.date_end : ""} ${e.title || ""}`, `${e.note || ""}`, "timeline.html", (e.date_type || "") === "confirmed" ? "已公布" : "");
    });

    /* 自考真题套卷 */
    ((SITE_DATA.zikao || {}).papers || []).forEach(p => {
      push("真题", p.title || `${p.course_code} 真题`, `${p.course_code || ""} ${p.source_platform || ""}`, "past-papers.html", p.source_platform || "");
    });

    /* 刷题题库 */
    (SITE_DATA.quiz || []).forEach((q, i) => {
      push("刷题", `${q.subject || ""} 第 ${q.qno || i + 1} 题`, q.stem || "", "quiz.html", q.track || "");
    });

    /* 考前资料（HEUOpenResource/heu-icicles） */
    (window.MATERIALS || []).forEach(g => {
      g.items.forEach(it => {
        push("考前资料", `${g.name} · ${it.name}`, `${g.id} ${g.origin} ${g.note || ""}`, "materials.html", g.track === "zikao" ? `自考 ${g.id}` : "哈工程课程");
      });
    });

    return idx;
  }

  function search(idx, kw) {
    const terms = kw.trim().toLowerCase().split(/\s+/).filter(Boolean);
    if (!terms.length) return [];
    const hits = [];
    idx.forEach(item => {
      const title = item.title.toLowerCase();
      const text = item.text.toLowerCase();
      let score = 0, firstPos = -1;
      for (const t of terms) {
        const inTitle = title.indexOf(t);
        const inText = text.indexOf(t);
        if (inTitle === -1 && inText === -1) { score = -1; break; } /* AND 匹配 */
        if (inTitle !== -1) score += 10 * (title.split(t).length - 1);
        if (inText !== -1) {
          const n = text.split(t).length - 1;
          score += Math.min(n, 20);
          if (firstPos === -1 || (inText < firstPos)) firstPos = inText;
        }
      }
      if (score > 0) hits.push({ item, score, firstPos });
    });
    hits.sort((a, b) => b.score - a.score);
    return hits.slice(0, 60);
  }

  function snippet(item, pos, terms) {
    const raw = item.text;
    if (pos < 0) return "";
    const start = Math.max(0, pos - 30);
    let s = (start > 0 ? "…" : "") + raw.slice(start, pos + 130) + (start + 130 < raw.length ? "…" : "");
    terms.forEach(t => {
      try { s = s.replace(new RegExp(t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi"), m => `<mark>${m}</mark>`); } catch (e) {}
    });
    return s;
  }

  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  document.addEventListener("DOMContentLoaded", () => {
    const root = document.getElementById("search-results");
    const input = document.getElementById("search-page-input");
    if (!root) return;
    const idx = buildIndex();
    const info = document.getElementById("search-info");

    function run() {
      const kw = new URLSearchParams(location.search).get("kw") || "";
      if (input && input.value !== kw) input.value = kw;
      if (!kw.trim()) {
        info.textContent = `输入关键词开始搜索（共索引 ${idx.length} 条内容：课程、大纲考点、笔记要点与详解、数学小节、时间线、真题、刷题）`;
        root.innerHTML = "";
        return;
      }
      const terms = kw.trim().toLowerCase().split(/\s+/).filter(Boolean);
      const hits = search(idx, kw);
      info.textContent = `关键词「${kw}」：${hits.length} 条结果（多关键词为同时包含匹配；点击结果跳转到对应章节）`;
      const groups = {};
      hits.forEach(h2 => { (groups[h2.item.cat] = groups[h2.item.cat] || []).push(h2); });
      const catOrder = ["课程", "大纲考点", "课程笔记", "高中数学", "408 大纲", "时间线", "真题", "刷题"];
      root.innerHTML = catOrder.filter(c => groups[c]).map(cat => `
        <div class="sgroup">
          <h3>${cat} <span class="muted" style="font-size:12.5px;font-weight:400;">${groups[cat].length} 条</span></h3>
          ${groups[cat].map(({ item, firstPos }) => `
            <a class="shitem" href="${item.href}">
              <div class="sh-title">${esc(item.title)} ${item.extra ? `<span class="badge code">${esc(item.extra)}</span>` : ""}</div>
              <div class="sh-snip">${snippet(item, firstPos, terms)}</div>
            </a>`).join("")}
        </div>`).join("") || `<p class="muted">没有找到匹配内容。试试更短的关键词，如「散列」「导数」「队列」。</p>`;
    }
    if (input) input.addEventListener("keydown", e => {
      if (e.key === "Enter") location.href = "search.html?kw=" + encodeURIComponent(input.value.trim());
    });
    run();
  });
})();
